// Prepare message payload and template selection
const body = $input.item.json.body || $input.item.json;

return [{
  json: {
    patient_id: body.patient_id,
    patient_name: body.patient_name,
    phone: body.phone,
    language: body.language || 'ta',
    channel: body.channel || 'whatsapp',
    message: body.message,
    followup_id: body.followup_id,
    due_date: body.due_date,
    dispatched_at: new Date().toISOString()
  }
}];

// Logic for WhatsApp Cloud API or SMS provider
// When connecting Meta Cloud API, insert Meta WhatsApp node here.
// When connecting Twilio or Fast2SMS, configure provider credentials.
const item = $input.item.json;

console.log(`[n8n WhatsApp Outreach] Sending to ${item.phone}: ${item.message}`);

return [{
  json: {
    ...item,
    delivery_gateway: 'whatsapp_cloud_api',
    delivery_status: 'SENT'
  }
}];
